#!/usr/bin/env bash
# Checks that the chart's RBAC rules match config/rbac (generated by `make manifests`).
# The chart copies are hand-kept, so this catches drift. Works on macOS (bash 3.2, BSD awk).
set -u
cd "$(dirname "$0")/.."

SRC=config/rbac
DST=dist/chart/templates/rbac
fail=0
paired=" "   # config/rbac files that have a chart pair

# rules FILE [KIND]: print the text of the first top-level "rules:" block
# (of the document with that kind, if KIND is given). It stops at the next top-level
# line, which includes Helm "{{- end }}" lines. Quotes are dropped: the chart does not keep them.
rules() {
  awk -v want="${2:-}" '
    /^---/        { on = 0; kind = "" }
    /^kind:/      { kind = $2 }
    /^rules:/     { on = (want == "" || kind == want); if (on) print; next }
    /^[A-Za-z{]/  { on = 0 }
    on            { gsub(/"/, ""); print }
  ' "$1"
}

# pair SRC_FILE SRC_KIND DST_FILE DST_KIND
pair() {
  local s="$SRC/$1" d="$DST/$3"
  paired="$paired$1 "
  for f in "$s" "$d"; do
    [ -f "$f" ] || { echo "FAIL: missing file $f" >&2; fail=1; return; }
  done
  local a b
  a=$(rules "$s" "$2")
  b=$(rules "$d" "$4")
  [ -n "$a" ] || { echo "FAIL: empty or missing rules: block in $s${2:+ ($2)}" >&2; fail=1; return; }
  [ -n "$b" ] || { echo "FAIL: empty or missing rules: block in $d${4:+ ($4)}" >&2; fail=1; return; }
  if [ "$a" != "$b" ]; then
    echo "FAIL: rules differ between $s${2:+ ($2)} and $d${4:+ ($4)}" >&2
    diff -u <(echo "$a") <(echo "$b") --label "$s" --label "$d" >&2
    fail=1
  fi
}

pair role.yaml ClusterRole manager-role.yaml ""
pair role.yaml Role claim-role.yaml Role
pair leader_election_role.yaml "" leader-election-role.yaml ""
pair metrics_auth_role.yaml "" metrics-auth-role.yaml ""
pair metrics_reader_role.yaml "" metrics-reader.yaml ""
for crd in networkisolation workloadhardening; do
  for r in admin editor viewer; do
    pair "${crd}_${r}_role.yaml" "" "${crd}-${r}-role.yaml" ""
  done
done

# Every other file in config/rbac must be a binding, the service account or the kustomization.
for f in "$SRC"/*.yaml; do
  n=$(basename "$f")
  case "$n" in
    *_binding.yaml | service_account.yaml | kustomization.yaml) continue ;;
  esac
  case "$paired" in
    *" $n "*) ;;
    *) echo "FAIL: $f has no chart pair in hack/check-chart-rbac.sh" >&2; fail=1 ;;
  esac
done

[ "$fail" -eq 0 ] && echo "rbac-check: chart RBAC rules match config/rbac"
exit "$fail"
